        GetCSVLines(catalogItem) {
            const rawData = catalogItem.GetRawData();
            const catalogItemCSV = this.config.GetCatalogHeaderAttributes().map((attr) => { var _a; return ((_a = rawData[attr]) === null || _a === void 0 ? void 0 : _a.toString()) || ""; });
            const csvLines = [];
